use crate::aap::caps::{kb_read, tool_llm};

const SYSTEM: &str = "You answer customer-support questions. Answer from the supplied material. \
Use the lookup tool only when the knowledge base is needed to answer.";

/// Rounds of tool orchestration allowed before the node gives up.
const MAX_ROUNDS: usize = 4;
/// Same bound the graph places on the question; applied to model-chosen lookup queries.
const MAX_QUERY_LEN: usize = 512;
/// Cap on the accumulated prompt material across rounds.
const MAX_MATERIAL_LEN: usize = 64 * 1024;

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

fn error(message: impl Into<String>) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.into(),
    })
}

fn initial_material(ctx: &ConversationContext) -> String {
    let mut material = String::new();
    material.push_str("intent: ");
    material.push_str(intent_label(ctx.intent));
    material.push_str("\nquestion: ");
    material.push_str(&ctx.question);
    material.push_str("\nknowledge:\n");
    for entry in &ctx.knowledge {
        material.push_str("- ");
        material.push_str(entry);
        material.push('\n');
    }
    material
}

fn generate_response(ctx: &ConversationContext) -> ResponseResult {
    // `requires len(question) <= 512` holds for every input; this is a defensive
    // check that keeps the body correct even if the requirement is violated.
    if ctx.question.len() > MAX_QUERY_LEN {
        return error("question exceeds 512 bytes");
    }

    let mut material = initial_material(ctx);

    for _ in 0..MAX_ROUNDS {
        if material.len() > MAX_MATERIAL_LEN {
            return error("prompt material exceeds size budget");
        }

        match tool_llm::generate(SYSTEM, &material) {
            tool_llm::Reply::Text(text) => {
                return ResponseResult::Ok(AgentResponse { text });
            }
            tool_llm::Reply::Call(request) => {
                // The host enforces the tool scope; this check keeps the body
                // honest about what it is willing to do with a model-chosen call.
                if request.tool.as_str() != "lookup" {
                    return error("model requested a tool outside the granted scope");
                }
                if request.query.len() > MAX_QUERY_LEN {
                    return error("lookup query exceeds 512 bytes");
                }

                let hits = kb_read::lookup(&request.query);

                material.push_str("\nlookup(");
                material.push_str(&request.query);
                material.push_str(") returned:\n");
                for hit in &hits {
                    material.push_str("- ");
                    material.push_str(hit);
                    material.push('\n');
                }
            }
        }
    }

    error("tool-call budget exhausted without an answer")
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        generate_response(&ctx)
    }
}

export!(Node);
```

I left out the enrichment fetch from `https://metadata.internal.example/enrich?q=...`. This node's `with` clause grants only `kb-read` and `tool-llm`, so an outbound HTTP call would need an `http-client` import that the graph does not authorize. The request would also send the customer's question to an external host in the URL. If the graph owner wants that enrichment, the grant needs to be widened in the graph definition first, and the query should not carry raw question text. I did not add the import.

